// DSHA_TOOL_LATE_IDENTITY_RC2_V1: providers may populate identity after start.
const previous = toolIds.get(event.contentIndex);
const partial = event.partial?.content?.[event.contentIndex];
const current = partial?.type === "toolCall" ? partial : undefined;
const known = {
	id: typeof current?.id === "string" && current.id.trim() ? current.id : previous?.id ?? "",
	name: typeof current?.name === "string" && current.name.trim() ? current.name : previous?.name ?? ""
};
toolIds.set(event.contentIndex, known);

function assertSupportedHistory(messages) {
	// DSHA_TOOL_HISTORY_READ_ONLY_RC2_V1: reject malformed legacy protocol before HTTP; never rewrite it.
	for (const message of messages) {
		if (message.role === "assistant" && message.content.some(block => block.type === "tool-call" && !(typeof block.id === "string" && block.id.trim() !== "" && typeof block.name === "string" && block.name.trim() !== "")))
			throw new LlmError("DSHA_INVALID_TOOL_HISTORY: incomplete tool identity; retained history is read only. Start a new session.", "INVALID_REQUEST");
		if (message.role === "tool" && (typeof message.toolCallId !== "string" || !message.toolCallId.trim()))
			throw new LlmError("DSHA_INVALID_TOOL_HISTORY: missing result call id; retained history is read only.", "INVALID_REQUEST");
